import { execFile } from "node:child_process";
import { access, readFile, rm, writeFile } from "node:fs/promises";
import { hostname } from "node:os";
import { Injectable } from "@nestjs/common";
import { currentOperatingSystem } from "../os/current-operating-system.js";
import { IdentityFolder } from "./identity-folder.js";

const KEYGEN_TIMEOUT_MS = 30_000;

/**
 * The Office ssh key (spec §5.5 Defaults, the Office identity): generated by The Office the first
 * time it is needed, kept in the identity folder, its private half readable by its owner only. The
 * user adds the public half to the hosts that need it.
 */
@Injectable()
export class OfficeSshKey {
  readonly privateKeyPath: string;
  readonly publicKeyPath: string;
  private readonly keygen = currentOperatingSystem().sshPrograms.keygen;
  private ready: Promise<void> | undefined;

  constructor(private readonly folder: IdentityFolder) {
    this.privateKeyPath = folder.file("office_ssh_key");
    this.publicKeyPath = `${this.privateKeyPath}.pub`;
  }

  /** The public half, in the `ssh-ed25519 <key> <comment>` form a host takes. */
  async publicKey(): Promise<string> {
    await this.ensure();
    return (await readFile(this.publicKeyPath, "utf8")).trim();
  }

  /** Whether the key has been made, without making it. */
  isMade(): Promise<boolean> {
    return exists(this.privateKeyPath);
  }

  /**
   * Makes the key if it isn't there, once per process: both halves, or the public half again from
   * a private half left alone. A public half without its private one is no key and is replaced.
   */
  ensure(): Promise<void> {
    this.ready ??= this.make().catch((error: unknown) => {
      this.ready = undefined;
      throw error;
    });
    return this.ready;
  }

  private async make(): Promise<void> {
    await this.folder.prepare();
    if (await exists(this.privateKeyPath)) {
      if (!(await exists(this.publicKeyPath))) {
        const publicHalf = await this.runKeygen(["-y", "-f", this.privateKeyPath]);
        await writeFile(this.publicKeyPath, publicHalf, { mode: 0o600 });
      }
    } else {
      await rm(this.publicKeyPath, { force: true });
      await this.runKeygen([
        "-q",
        "-t",
        "ed25519",
        "-N",
        "",
        "-C",
        `the-office@${hostname()}`,
        "-f",
        this.privateKeyPath,
      ]);
    }
    await currentOperatingSystem().restrictToOwner(this.privateKeyPath, "file");
  }

  private runKeygen(keygenArguments: readonly string[]): Promise<string> {
    return new Promise((resolve, reject) => {
      const child = execFile(
        this.keygen,
        keygenArguments,
        { timeout: KEYGEN_TIMEOUT_MS, windowsHide: true },
        (error, stdout, stderr) => {
          if (!error) return resolve(stdout);
          const reason = stderr.trim() || error.message;
          reject(
            new Error(`ssh-keygen could not make the Office ssh key: ${reason}`, { cause: error }),
          );
        },
      );
      // Nothing to answer: a question, such as whether to overwrite, ends it instead of waiting.
      child.stdin?.end();
    });
  }
}

async function exists(path: string): Promise<boolean> {
  return access(path).then(
    () => true,
    () => false,
  );
}
